import { Link } from 'react-router-dom';

interface NavItemProps {
  to: string;
  icon: 'folder' | 'shared' | 'bin' | 'settings';
  label: string;
  active: boolean;
}

const ICON_MAP: Record<NavItemProps['icon'], string> = {
  folder: '\uD83D\uDCC1',
  shared: '\uD83D\uDD17',
  bin: '\uD83D\uDDD1',
  settings: '\u2699',
};

/**
 * Navigation item component.
 * Renders a sidebar navigation link with emoji icon.
 */
export function NavItem({ to, icon, label, active }: NavItemProps) {
  const iconEmoji = ICON_MAP[icon];

  const className = active ? 'nav-item nav-item--active' : 'nav-item';

  return (
    <Link to={to} className={className} data-testid={`nav-item-${label.toLowerCase()}`}>
      <span className="nav-item-icon">{iconEmoji}</span>
      <span className="nav-item-label">{label}</span>
    </Link>
  );
}

import { useLocation } from 'react-router-dom';
import { NavItem } from './NavItem';
import { StorageQuota } from './StorageQuota';

/**
 * App sidebar component.
 * Contains navigation items and storage quota indicator.
 */
export function AppSidebar() {
  const location = useLocation();

  return (
    <aside className="app-sidebar" data-testid="app-sidebar">
      <nav className="sidebar-nav">
        <NavItem
          to="/files"
          icon="folder"
          label="Files"
          active={location.pathname.startsWith('/files')}
        />
        <NavItem
          to="/shared"
          icon="shared"
          label="Shared"
          active={location.pathname.startsWith('/shared')}
        />
        <NavItem to="/bin" icon="bin" label="Bin" active={location.pathname.startsWith('/bin')} />
        <NavItem
          to="/settings"
          icon="settings"
          label="Settings"
          active={location.pathname === '/settings'}
        />
      </nav>
      <div className="sidebar-footer">
        <StorageQuota />
      </div>
    </aside>
  );
}

